// Plugin pages.
// /<slug>/ pages are generated by scripts/build.py (data-static): here we only wire up the gallery
// and refresh the download count. plugin.html?p=<slug> is the fallback for a plugin that was published
// after the last build: it renders the same page live from Modrinth.
const page = document.getElementById("page");

function wireGallery(gallery) {
  const img = document.getElementById("g-img");
  const cap = document.getElementById("g-cap");
  if (!img || !gallery.length) return;
  const show = (i) => {
    const g = gallery[i];
    img.src = g.url; img.alt = g.title || "";
    cap.innerHTML = `${g.title ? `<b>${esc(g.title)}</b>` : ""}${esc(g.description || "")}`;
    cap.hidden = !(g.title || g.description);
    page.querySelectorAll(".g-thumbs button").forEach((b) => b.setAttribute("aria-current", String(+b.dataset.i === i)));
  };
  page.querySelectorAll(".g-thumbs button").forEach((b) => b.addEventListener("click", () => show(+b.dataset.i)));
  return show;
}

function openLinksInNewTab() {
  page.querySelectorAll(".md a[href^='http']").forEach((a) => { a.target = "_blank"; a.rel = "noopener"; });
}

/* ---------- generated page ---------- */
async function enhanceStatic() {
  const data = JSON.parse(document.getElementById("page-data").textContent);
  wireGallery(data.gallery);
  openLinksInNewTab();
  if (data.local) return;
  try {
    const r = await fetch(`${API}/project/${encodeURIComponent(data.slug)}`);
    if (!r.ok) return;
    const p = await r.json();
    const set = (k, v) => page.querySelectorAll(`[data-live="${k}"]`).forEach((el) => (el.textContent = nf.format(v)));
    set("downloads", p.downloads);
    set("followers", p.followers);
  } catch { /* the built numbers stay */ }
}

/* ---------- live fallback: plugin.html?p=<slug> ---------- */
const params = new URLSearchParams(location.search);
const slug = params.get("p") || "";

function md(text) {
  return DOMPurify.sanitize(marked.parse(text || "", { gfm: true }), { ADD_ATTR: ["align", "target"] });
}

function notFound() {
  document.title = "Not found – Invv";
  page.innerHTML = `<div class="loading">
    <p>There's no plugin called “${esc(slug)}”.</p>
    <p><a class="btn" href="/#all">See all plugins</a></p></div>`;
}

async function getJson(url) {
  const r = await fetch(url);
  if (!r.ok) throw new Error(r.status);
  return r.json();
}

async function loadLive() {
  if (!slug) return notFound();
  // a generated page exists: go there (unless we were sent here because it didn't)
  const built = (typeof SNAPSHOT !== "undefined" && SNAPSHOT.some((x) => x.slug === slug)) || (typeof LOCAL !== "undefined" && LOCAL[slug]);
  if (built && !params.has("from404")) return location.replace(`/${encodeURIComponent(slug)}/`);

  const all = await loadProjects();
  fillFooter(all);
  let p, versions;
  try {
    [p, versions] = await Promise.all([
      getJson(`${API}/project/${encodeURIComponent(slug)}`),
      getJson(`${API}/project/${encodeURIComponent(slug)}/version`).catch(() => []),
    ]);
  } catch {
    return notFound();
  }
  const gallery = [...(p.gallery || [])].sort((a, b) => (b.featured - a.featured) || (a.ordering - b.ordering))
    .map((g) => ({ url: g.url, title: g.title, description: g.description }));
  render(p, p.body, gallery, versions, all);
}

function render(p, body, gallery, versions, all) {
  document.title = `${p.title} – Invv`;
  const latest = versions[0];
  const facts = [
    `<span class="chip"><b>${nf.format(p.downloads)}</b> downloads</span>`,
    p.followers ? `<span class="chip"><b>${nf.format(p.followers)}</b> followers</span>` : "",
    `<span class="chip">Minecraft <b>${esc(versionRange(p))}</b></span>`,
    `<span class="chip">${esc(platforms(p))}</span>`,
    `<span class="chip">Updated <b>${ago(p.updated)}</b></span>`,
  ].join("");
  const verList = versions.length
    ? `<ul class="vers">${versions.slice(0, 6).map((v) => {
        const gv = v.game_versions.filter((x) => /^\d/.test(x));
        const range = gv.length > 1 ? `${gv[0]} – ${gv[gv.length - 1]}` : gv[0] || "";
        return `<li><div><b>${esc(v.version_number)}</b><span>${esc(range)} · ${ago(v.date_published)}</span></div>
          <a href="${modrinthUrl(p)}/version/${encodeURIComponent(v.id)}">Download</a></li>`;
      }).join("")}</ul>
      <p class="box-more"><a href="${modrinthUrl(p)}/versions">All versions on Modrinth</a></p>`
    : `<p class="box-note">No files yet.</p>`;
  const links = [
    [modrinthUrl(p), "Modrinth page"],
    p.source_url && [p.source_url, "Source code"],
    p.issues_url && [p.issues_url, "Issue tracker"],
    p.wiki_url && [p.wiki_url, "Wiki"],
    ["https://discord.gg/E9hpUj3E6G", "Discord, for help and bug reports"],
  ].filter(Boolean).map(([u, t]) => `<li><a href="${esc(u)}">${esc(t)}</a></li>`).join("");
  const others = all.filter((x) => x.slug !== p.slug).sort((a, b) => b.downloads - a.downloads).slice(0, 4);

  page.innerHTML = `
    <section class="p-hero" style="--glow:${glow(p, .35)}">
      ${gallery[0] ? `<div class="bgimg" style="background-image:url('${esc(gallery[0].url)}')"></div>` : ""}
      <div class="p-hero-inner">
        <p class="crumb"><a href="/">Home</a> / <a href="/#all">${typeOf(p)}s</a> / ${esc(p.title)}</p>
        <img class="p-icon" src="${esc(p.icon_url)}" alt="" width="128" height="128">
        <div class="p-title"><h1>${esc(p.title)}</h1><p>${esc(p.description)}</p></div>
        <div class="p-actions">
          ${latest ? `<a class="btn" href="${modrinthUrl(p)}/version/${encodeURIComponent(latest.id)}">Download ${esc(latest.version_number)}</a>` : ""}
          <a class="btn btn-ghost" href="${modrinthUrl(p)}">Open on Modrinth</a>
        </div>
        <div class="p-facts">${facts}</div>
      </div>
    </section>
    <div class="p-body">
      <div>
        ${gallery.length ? `<div class="gallery">
          <figure class="g-main" style="margin:0">
            <img id="g-img" src="${esc(gallery[0].url)}" alt="">
            <figcaption class="g-cap" id="g-cap" hidden></figcaption>
          </figure>
          ${gallery.length > 1 ? `<div class="g-thumbs" role="list">${gallery.map((g, i) =>
            `<button type="button" data-i="${i}" aria-current="${i === 0}" aria-label="Show screenshot ${i + 1}">
              <img src="${esc(g.url)}" alt="" loading="lazy"></button>`).join("")}</div>` : ""}
        </div>` : ""}
        <article class="md">${md(body)}</article>
      </div>
      <aside class="side">
        <div class="box"><h2>Latest versions</h2>${verList}</div>
        <div class="box"><h2>Links</h2><ul class="links">${links}</ul></div>
      </aside>
    </div>
    <section class="others">
      <div class="block-head center"><h2>More plugins</h2></div>
      <ul class="grid">${others.map(cardHtml).join("")}</ul>
    </section>`;
  wireGallery(gallery)?.(0);
  openLinksInNewTab();
}

if (page.hasAttribute("data-static")) enhanceStatic();
else loadLive();
